unsigned char *detach_blob(BlobInfo *blob_info) {
    if (blob_info == NULL) {
        return NULL;
    }

    if (blob_info->data == NULL) {
        return NULL;
    }

    // If debugging is enabled, log the detach event
#ifdef DEBUG
    printf("Detaching blob from BlobInfo structure.\n");
#endif

    // Unmap the blob data if mapped
    if (blob_info->is_mapped) {
        munmap(blob_info->data, blob_info->length);
        blob_info->data = NULL;
        blob_info->is_mapped = 0;
    }

    // Save the data pointer before resetting it
    unsigned char *detached_data = blob_info->data;
    blob_info->data = NULL;
    blob_info->length = 0;

    return detached_data;
}

